func testOrdemServicoToOneSetOpEntidadeUsingEnt(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrdemServico
	var b, c Entidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, ordemServicoDBTypes, false, strmangle.SetComplement(ordemServicoPrimaryKeyColumns, ordemServicoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, entidadeDBTypes, false, strmangle.SetComplement(entidadePrimaryKeyColumns, entidadeColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, entidadeDBTypes, false, strmangle.SetComplement(entidadePrimaryKeyColumns, entidadeColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Entidade{&b, &c} {
		err = a.SetEnt(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Ent != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.EntOrdemServicos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.EntID != x.EntID {
			t.Error("foreign key was wrong value", a.EntID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.EntID))
		reflect.Indirect(reflect.ValueOf(&a.EntID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.EntID != x.EntID {
			t.Error("foreign key was wrong value", a.EntID, x.EntID)
		}
	}
}
